/**
 * Health Records Page Component
 * Generated by Zhuang
 */
import React, { useState, useEffect, useCallback } from 'react';
import {
  Card,
  Button,
  Table,
  Modal,
  Form,
  Input,
  InputNumber,
  DatePicker,
  Tag,
  Space,
  message,
  Popconfirm,
  Row,
  Col,
  Typography,
  Upload,
  Alert,
  Divider,
} from 'antd';
import {
  PlusOutlined,
  EditOutlined,
  DeleteOutlined,
  DownloadOutlined,
  UploadOutlined,
  CloudUploadOutlined,
} from '@ant-design/icons';
import dayjs from 'dayjs';
import { healthAPI } from '../services/api';
import { useMember } from '../context/MemberContext';
import TagSelector from '../components/TagSelector';
import { tagValueToLabel } from '../utils/tagI18n';
import { useTranslation } from 'react-i18next';
import { formatServerTime, parseServerTime } from '../utils/date';
import { computeThresholdStatus, getStatusColor, getStatusText } from '../utils/thresholdCalculator';
import HealthStandardsReference from '../components/HealthStandardsReference';

const { TextArea } = Input;
const { Title } = Typography;
const { Dragger } = Upload;

const HealthRecords = () => {
  const { t } = useTranslation();
  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(false);
  const [modalVisible, setModalVisible] = useState(false);
  const [editingRecord, setEditingRecord] = useState(null);
  const [form] = Form.useForm();
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 10,
    total: 0,
  });
  const { selectedMemberId } = useMember();
  const [filters, setFilters] = useState({
    tags: [],
    dateRange: null,
  });
  // Generated by Zhuang: dynamic tag options
  const [tagOptions, setTagOptions] = useState([]);
  // Active threshold configuration for dynamic status computation
  const [activeThreshold, setActiveThreshold] = useState(null);
  
  // Batch import states
  const [batchImportModalVisible, setBatchImportModalVisible] = useState(false);
  const [batchImportFile, setBatchImportFile] = useState(null);
  const [batchImportLoading, setBatchImportLoading] = useState(false);
  const [batchImportResult, setBatchImportResult] = useState(null);
  const [batchImportStep, setBatchImportStep] = useState('upload'); // 'upload' or 'result'

  // Fetch active threshold configuration
  const fetchActiveThreshold = useCallback(async () => {
    try {
      const response = await healthAPI.getActiveThreshold();
      if (response.data && response.data.profile) {
        setActiveThreshold({
          payload: JSON.parse(response.data.profile.payload),
          version: response.data.version
        });
      }
    } catch (error) {
      // Silently handle - no active threshold is acceptable
      console.log('No active threshold configuration');
    }
  }, []);

  useEffect(() => {
    fetchActiveThreshold();
  }, [fetchActiveThreshold]);

  const fetchRecords = useCallback(async () => {
    try {
      setLoading(true);
      
      const params = {
        page: pagination.current,
        size: pagination.pageSize, // Generated by Zhuang: backend expects 'size'
      };

      if (filters.tags.length) {
        params.tags = filters.tags.join(',');
      }

      if (filters.dateRange) {
        params.date_from = filters.dateRange[0].startOf('day').toDate().toISOString();
        params.date_to = filters.dateRange[1].endOf('day').toDate().toISOString();
      }

  if (selectedMemberId !== undefined && selectedMemberId !== null) {
        params.subject_member_id = selectedMemberId;
      }

  const response = await healthAPI.getRecords(params);
      const data = response.data;

      setRecords(data.records || []);
  // Generated by Zhuang: collect unique tags from current page
  const uniq = new Set();
  (data.records || []).forEach(r => (r.tags || []).forEach(t => uniq.add(t)));
  setTagOptions(prev => Array.from(new Set([...(prev || []), ...Array.from(uniq)])));
      // Only update when total actually changes to avoid unnecessary re-renders
      setPagination(prev => {
        const newTotal = data.pagination?.total || 0;
        if (prev.total === newTotal) return prev;
        return { ...prev, total: newTotal };
      });
    } catch (error) {
      console.error('Failed to fetch records:', error);
  message.error(t('health.messages.loadFail'));
    } finally {
      setLoading(false);
    }
  }, [pagination, filters, selectedMemberId, t]); // Generated by Zhuang

  // Generated by Zhuang: also fetch a larger set once per member change
  useEffect(() => {
    const fetchAllForMember = async () => {
      try {
        const params = { page: 1, size: 1000 };
        if (selectedMemberId !== undefined && selectedMemberId !== null) {
          params.subject_member_id = selectedMemberId;
        }
        const resp = await healthAPI.getRecords(params);
        const uniq = new Set();
        (resp.data?.records || []).forEach(r => (r.tags || []).forEach(t => uniq.add(t)));
        setTagOptions(Array.from(uniq));
      } catch (e) {
        // ignore
      }
    };
    fetchAllForMember();
  }, [selectedMemberId]);

  useEffect(() => {
    fetchRecords();
  }, [fetchRecords]);

  const handleAdd = () => {
  setEditingRecord(null);
    form.resetFields();
    form.setFieldsValue({
      timestamp: dayjs(),
    });
    setModalVisible(true);
  };

  const handleEdit = (record) => {
    setEditingRecord(record);
    form.setFieldsValue({
      systolic_pressure: record.systolic,
      diastolic_pressure: record.diastolic,
      heart_rate: record.heart_rate,
      timestamp: parseServerTime(record.timestamp),
      tags: record.tags || [],
      notes: record.note,
    });
    setModalVisible(true);
  };

  const handleDelete = async (recordId) => {
    try {
      await healthAPI.deleteRecord(recordId);
      message.success(t('health.messages.deleteSuccess'));
      fetchRecords();
    } catch (error) {
      console.error('Failed to delete record:', error);
      message.error(t('health.messages.deleteFail'));
    }
  };

  const handleSubmit = async (values) => {
    try {
      const recordData = {
        systolic: values.systolic_pressure,
        diastolic: values.diastolic_pressure,
        heart_rate: values.heart_rate,
        timestamp: values.timestamp.toISOString(),
        tags: values.tags || [],
        note: values.notes,
      };

  if (selectedMemberId !== undefined && selectedMemberId !== null) {
        recordData.subject_member_id = selectedMemberId;
      }

      if (editingRecord) {
        await healthAPI.updateRecord(editingRecord.id, recordData);
        message.success(t('health.messages.updateSuccess'));
      } else {
        await healthAPI.createRecord(recordData);
        message.success(t('health.messages.addSuccess'));
      }

      setModalVisible(false);
      fetchRecords();
    } catch (error) {
      console.error('Failed to save record:', error);
      const errorMessage = error.response?.data?.message || t('health.messages.saveFail');
      message.error(errorMessage);
    }
  };

  const handleTableChange = (newPagination) => {
    setPagination(prev => ({
      ...prev,
      current: newPagination.current,
      pageSize: newPagination.pageSize,
    }));
  };

  // Generated by Zhuang: inline filter handlers
  const handleDateRangeChange = (range) => {
    setFilters(prev => ({ ...prev, dateRange: range }));
    setPagination(prev => ({ ...prev, current: 1 }));
  };

  const handleTagsChange = (tags) => {
    setFilters(prev => ({ ...prev, tags }));
    setPagination(prev => ({ ...prev, current: 1 }));
  };

  // Removed unused helper removeTagFilter - not used by current UI

  const columns = [
    {
      title: t('health.columns.time'),
      dataIndex: 'timestamp',
      key: 'timestamp',
      render: (timestamp) => formatServerTime(timestamp),
      sorter: true,
    },
    {
      title: t('health.columns.bp'),
      key: 'blood_pressure',
      render: (_, record) => {
        // Backend fields are `systolic` and `diastolic`
        if (record.systolic && record.diastolic) {
          // Dynamically compute status
          const status = computeThresholdStatus(
            record.systolic,
            record.diastolic,
            record.heart_rate,
            activeThreshold
          );
          
          return (
            <Space>
              <span>{`${record.systolic}/${record.diastolic} mmHg`}</span>
              {status && (
                <Tag color={getStatusColor(status)}>
                  {getStatusText(status, t)}
                </Tag>
              )}
            </Space>
          );
        }
        return '-';
      },
    },
    {
      title: t('health.columns.hr'),
      dataIndex: 'heart_rate',
      key: 'heart_rate',
      render: (heartRate) => heartRate ? `${heartRate} bpm` : '-',
    },
    {
      title: t('health.columns.tags'),
      dataIndex: 'tags',
      key: 'tags',
      render: (tags) => (
        <Space wrap>
          {(tags || []).map(tag => (
            <Tag key={tag} color="blue">{tagValueToLabel(tag, t)}</Tag>
          ))}
        </Space>
      ),
    },
    {
      title: t('health.columns.note'),
  dataIndex: 'note',
  key: 'note',
  render: (note) => note || '-',
    },
    {
      title: t('health.columns.actions'),
      key: 'actions',
      render: (_, record) => (
        <Space>
          <Button
            type="text"
            icon={<EditOutlined />}
            onClick={() => handleEdit(record)}
          >
            {t('health.edit')}
          </Button>
          <Popconfirm
            title={t('health.messages.deleteConfirm')}
            onConfirm={() => handleDelete(record.id)}
            okText={t('health.form.save')}
            cancelText={t('health.form.cancel')}
          >
            <Button
              type="text"
              danger
              icon={<DeleteOutlined />}
            >
              {t('health.delete')}
            </Button>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  const handleExport = async () => {
    try {
      const params = {};
      if (filters.tags?.length) params.tags = filters.tags.join(',');
      if (filters.dateRange) {
        params.date_from = filters.dateRange[0].startOf('day').toDate().toISOString();
        params.date_to = filters.dateRange[1].endOf('day').toDate().toISOString();
      }
      if (selectedMemberId !== undefined && selectedMemberId !== null) {
        params.subject_member_id = selectedMemberId;
      }
      const resp = await healthAPI.exportCsv(params);
      const blob = new Blob([resp.data], { type: 'text/csv;charset=utf-8' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      // Generated by Zhuang: derive filename from Content-Disposition (supports RFC 5987 filename*)
      const cd = resp.headers && (resp.headers['content-disposition'] || resp.headers['Content-Disposition']);
      let filename = 'health_records.csv';
      if (cd) {
        // Try filename* first (RFC 5987)
  const fnStarMatch = /filename\*=UTF-8''([^;\n]+)/i.exec(cd);
        if (fnStarMatch && fnStarMatch[1]) {
          try {
            filename = decodeURIComponent(fnStarMatch[1]);
          } catch (_) { /* ignore decode error */ }
        } else {
          const fnMatch = /filename="?([^;\n"]+)"?/i.exec(cd);
          if (fnMatch && fnMatch[1]) {
            filename = fnMatch[1];
          }
        }
      }
      a.download = filename;
      a.click();
      window.URL.revokeObjectURL(url);
    } catch (e) {
      console.error('Export CSV failed', e);
  const msg = e.response?.data?.message || t('health.messages.exportFail');
      message.error(msg);
    }
  };

  // Batch import handlers
  const handleBatchImportOpen = () => {
    setBatchImportModalVisible(true);
    setBatchImportStep('upload');
    setBatchImportFile(null);
    setBatchImportResult(null);
  };

  const handleBatchImportClose = () => {
    setBatchImportModalVisible(false);
    setBatchImportFile(null);
    setBatchImportResult(null);
    setBatchImportStep('upload');
  };

  const handleTemplateDownload = async (format) => {
    try {
      const response = await healthAPI.downloadTemplate(format);
      const blob = new Blob([response.data]);
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = format === 'excel' 
        ? 'health_records_template.xlsx' 
        : 'health_records_template.csv';
      a.click();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Template download failed:', error);
      message.error(t('health.batchImport.messages.templateDownloadFail'));
    }
  };

  const handleBatchImport = async () => {
    if (!batchImportFile) {
      message.warning(t('health.batchImport.uploadHint'));
      return;
    }

    try {
      setBatchImportLoading(true);
      const formData = new FormData();
      formData.append('file', batchImportFile);

      const response = await healthAPI.batchImport(formData);
      const result = response.data;

      setBatchImportResult(result);
      setBatchImportStep('result');

      if (result.summary.error_count === 0) {
        message.success(
          t('health.batchImport.messages.importSuccess', { 
            count: result.summary.success_count 
          })
        );
        // Refresh records list
        fetchRecords();
      } else {
        message.warning(
          t('health.batchImport.messages.importPartialSuccess', {
            success: result.summary.success_count,
            failed: result.summary.error_count
          })
        );
      }
    } catch (error) {
      console.error('Batch import failed:', error);
      const errorMessage = error.response?.data?.message || t('health.batchImport.messages.importFail');
      message.error(errorMessage);
    } finally {
      setBatchImportLoading(false);
    }
  };

  const handleErrorLogDownload = async () => {
    if (!batchImportResult || !batchImportResult.errors || batchImportResult.errors.length === 0) {
      return;
    }

    try {
      const response = await healthAPI.downloadErrorLog(batchImportResult.errors);
      const blob = new Blob([response.data]);
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `import_errors_${Date.now()}.csv`;
      a.click();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Error log download failed:', error);
      message.error(t('health.batchImport.messages.errorLogDownloadFail'));
    }
  };

  const uploadProps = {
    name: 'file',
    multiple: false,
    maxCount: 1,
    accept: '.xlsx,.csv',
    beforeUpload: (file) => {
      // Check file size (5MB)
      const isLt5M = file.size / 1024 / 1024 < 5;
      if (!isLt5M) {
        message.error(t('health.batchImport.messages.fileTooLarge'));
        return Upload.LIST_IGNORE;
      }

      // Check file type
      const isValidType = file.name.endsWith('.xlsx') || file.name.endsWith('.csv');
      if (!isValidType) {
        message.error(t('health.batchImport.messages.invalidFormat'));
        return Upload.LIST_IGNORE;
      }

      setBatchImportFile(file);
      return false; // Prevent auto upload
    },
    onRemove: () => {
      setBatchImportFile(null);
    },
    fileList: batchImportFile ? [batchImportFile] : [],
  };

  return (
    <div>
      <div style={{ marginBottom: 8, display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 12 }}>
    <Title level={2}>{t('health.title')}</Title>
        <Space size={12} wrap>
          <Button
            icon={<CloudUploadOutlined />}
            onClick={handleBatchImportOpen}
          >
            {t('health.batchImport.button')}
          </Button>
          <Button
            icon={<DownloadOutlined />}
            onClick={handleExport}
          >
      {t('health.export')}
          </Button>
          <Button
            type="primary"
            icon={<PlusOutlined />}
            onClick={handleAdd}
          >
      {t('health.add')}
          </Button>
        </Space>
      </div>

      {/* Health Standards Reference - Generated by Copilot */}
      <HealthStandardsReference config={activeThreshold} />

      {/* Labeled inline filter bar - Generated by Zhuang */}
      <Card size="small" style={{ marginBottom: 8 }} styles={{ body: { padding: 12 } }}>
        <Form
          layout="inline"
          // Generated by Zhuang: keep filters strictly on one row
          style={{ display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'nowrap' }}
          className="filter-bar"
        >
          <Form.Item label={t('health.filters.date')} style={{ marginBottom: 0, flex: '0 0 auto' }}>
            <DatePicker.RangePicker
              data-testid="filter-date-range"
              value={filters.dateRange}
              onChange={handleDateRangeChange}
              style={{ width: 320 }}
            />
          </Form.Item>

          <Form.Item
            label={t('health.filters.tags')}
            // Generated by Zhuang: allow TagSelector to grow but also shrink to stay in one line
            style={{ marginBottom: 0, flex: '1 1 420px', minWidth: 260, alignItems: 'center' }}
            className="filter-tags-item"
          >
            <TagSelector
              data-testid="filter-tags"
              value={filters.tags}
              onChange={handleTagsChange}
              placeholder={t('health.filters.tags')}
              // Generated by Zhuang: width fills container; allow shrink with smaller minWidth
              style={{ width: '100%', minWidth: 260 }}
              maxTagCount="responsive"
              popupMatchSelectWidth={false}
              listHeight={320}
              options={tagOptions}
            />
          </Form.Item>

          <Form.Item style={{ marginLeft: 'auto', marginBottom: 0 }}>
            <Button onClick={() => { setFilters({ tags: [], dateRange: null }); setPagination(prev => ({ ...prev, current: 1 })); }}>{t('health.filters.clear')}</Button>
          </Form.Item>
        </Form>
      </Card>

  {/* Removed extra date chip row to avoid duplication - Generated by Zhuang */}

      <Card>
        <Table
          columns={columns}
          dataSource={records}
          rowKey="id"
          loading={loading}
          pagination={{
            ...pagination,
            showSizeChanger: true,
            showQuickJumper: true,
            showTotal: (total, range) => t('health.table.total', { start: range[0], end: range[1], total }),
          }}
          onChange={handleTableChange}
          scroll={{ x: 'max-content' }}
        />
      </Card>

      {/* Add/Edit Modal */}
      <Modal
    title={editingRecord ? t('health.modal.editTitle') : t('health.modal.addTitle')}
        open={modalVisible}
        onCancel={() => setModalVisible(false)}
        footer={null}
        width={600}
      >
        <Form
          form={form}
          layout="vertical"
          onFinish={handleSubmit}
        >
          <Form.Item
            name="timestamp"
      label={t('health.form.timestamp')}
      rules={[{ required: true, message: t('health.form.timestamp') }]}
          >
            <DatePicker
              data-testid="timestamp"
              showTime
              style={{ width: '100%' }}
              format="YYYY-MM-DD HH:mm"
            />
          </Form.Item>

          <Row gutter={16}>
            <Col span={12}>
              <Form.Item
                name="systolic_pressure"
                label={t('health.form.systolic')}
                dependencies={["diastolic_pressure"]}
                rules={[
                  { required: true, message: t('health.form.systolic') },
                  { type: 'number', min: 30, max: 250, message: t('health.validation.bpRange') },
                  {
                    validator: (_, value) => {
                      const d = form.getFieldValue('diastolic_pressure');
                      if (value === undefined || value === null || d === undefined || d === null) return Promise.resolve();
                      return value > d ? Promise.resolve() : Promise.reject(new Error(t('health.validation.bpRelation')));
                    }
                  }
                ]}
              >
                <InputNumber
                  data-testid="systolic-pressure"
                  placeholder={t('health.form.systolic')}
                  style={{ width: '100%' }}
                  precision={0}
                />
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item
                name="diastolic_pressure"
                label={t('health.form.diastolic')}
                dependencies={["systolic_pressure"]}
                rules={[
                  { required: true, message: t('health.form.diastolic') },
                  { type: 'number', min: 30, max: 250, message: t('health.validation.bpRange') },
                  {
                    validator: (_, value) => {
                      const s = form.getFieldValue('systolic_pressure');
                      if (value === undefined || value === null || s === undefined || s === null) return Promise.resolve();
                      return s > value ? Promise.resolve() : Promise.reject(new Error(t('health.validation.bpRelation')));
                    }
                  }
                ]}
              >
                <InputNumber
                  data-testid="diastolic-pressure"
                  placeholder={t('health.form.diastolic')}
                  style={{ width: '100%' }}
                  precision={0}
                />
              </Form.Item>
            </Col>
          </Row>

          <Form.Item
            name="heart_rate"
            label={t('health.form.heartRate')}
            rules={[
              { type: 'number', min: 30, max: 150, message: t('health.validation.hrRange') }
            ]}
          >
            <InputNumber
              data-testid="heart-rate"
              placeholder={t('health.form.heartRate')}
              style={{ width: '100%' }}
              precision={0}
            />
          </Form.Item>

          <Form.Item
            name="tags"
            label={t('health.form.tags')}
          >
            <TagSelector />
          </Form.Item>

          <Form.Item
            name="notes"
            label={t('health.form.notes')}
          >
            <TextArea
              data-testid="notes"
              placeholder={t('health.form.notes')}
              rows={3}
            />
          </Form.Item>

          <Form.Item shouldUpdate>
            {() => {
              const hasErrors = form.getFieldsError().some(({ errors }) => errors.length);
              const values = form.getFieldsValue();
              const missingRequired = !values.timestamp || values.systolic_pressure === undefined || values.diastolic_pressure === undefined;
              const disabled = hasErrors || missingRequired;
              return (
                <Space>
                  <Button type="primary" htmlType="submit" disabled={disabled}>
                    {editingRecord ? t('health.form.update') : t('health.form.save')}
                  </Button>
                  <Button onClick={() => setModalVisible(false)}>
                    {t('health.form.cancel')}
                  </Button>
                </Space>
              );
            }}
          </Form.Item>
        </Form>
      </Modal>

      {/* Batch Import Modal */}
      <Modal
        title={t('health.batchImport.title')}
        open={batchImportModalVisible}
        onCancel={handleBatchImportClose}
        width={700}
        footer={null}
      >
        {batchImportStep === 'upload' ? (
          <div>
            {/* Template Download Section */}
            <div style={{ marginBottom: 24 }}>
              <Title level={5}>{t('health.batchImport.downloadTemplate')}</Title>
              <Space>
                <Button
                  icon={<DownloadOutlined />}
                  onClick={() => handleTemplateDownload('excel')}
                >
                  {t('health.batchImport.templateExcel')}
                </Button>
                <Button
                  icon={<DownloadOutlined />}
                  onClick={() => handleTemplateDownload('csv')}
                >
                  {t('health.batchImport.templateCsv')}
                </Button>
              </Space>
            </div>

            <Divider />

            {/* File Upload Section */}
            <div style={{ marginBottom: 24 }}>
              <Title level={5}>{t('health.batchImport.uploadTitle')}</Title>
              <Dragger {...uploadProps}>
                <p className="ant-upload-drag-icon">
                  <UploadOutlined style={{ fontSize: 48, color: '#1890ff' }} />
                </p>
                <p className="ant-upload-text">{t('health.batchImport.uploadHint')}</p>
                <p className="ant-upload-hint">
                  {t('health.batchImport.uploadDescription')}
                </p>
              </Dragger>
            </div>

            {/* Action Buttons */}
            <div style={{ textAlign: 'right' }}>
              <Space>
                <Button onClick={handleBatchImportClose}>
                  {t('health.batchImport.cancel')}
                </Button>
                <Button
                  type="primary"
                  icon={<CloudUploadOutlined />}
                  onClick={handleBatchImport}
                  loading={batchImportLoading}
                  disabled={!batchImportFile}
                >
                  {t('health.batchImport.import')}
                </Button>
              </Space>
            </div>
          </div>
        ) : (
          <div>
            {/* Import Results */}
            <Title level={5}>{t('health.batchImport.results.title')}</Title>
            
            {batchImportResult && (
              <div>
                <Alert
                  message={
                    <div>
                      <div>{t('health.batchImport.results.total', { total: batchImportResult.summary.total_rows })}</div>
                      <div style={{ color: '#52c41a' }}>
                        {t('health.batchImport.results.success', { count: batchImportResult.summary.success_count })}
                      </div>
                      {batchImportResult.summary.error_count > 0 && (
                        <div style={{ color: '#ff4d4f' }}>
                          {t('health.batchImport.results.failed', { count: batchImportResult.summary.error_count })}
                        </div>
                      )}
                    </div>
                  }
                  type={batchImportResult.summary.error_count === 0 ? 'success' : 'warning'}
                  style={{ marginBottom: 16 }}
                />

                {batchImportResult.errors && batchImportResult.errors.length > 0 && (
                  <div style={{ marginBottom: 16 }}>
                    <Alert
                      message={`${t('health.batchImport.results.failed', { count: batchImportResult.errors.length })} - ${t('health.batchImport.results.downloadErrors')}`}
                      type="error"
                      showIcon
                    />
                    <div style={{ marginTop: 12, maxHeight: 300, overflow: 'auto', border: '1px solid #f0f0f0', padding: 12, borderRadius: 4 }}>
                      {batchImportResult.errors.slice(0, 10).map((err, idx) => (
                        <div key={idx} style={{ marginBottom: 8 }}>
                          <strong>Row {err.row}:</strong> {err.errors.join(', ')}
                        </div>
                      ))}
                      {batchImportResult.errors.length > 10 && (
                        <div style={{ marginTop: 8, color: '#666' }}>
                          ... and {batchImportResult.errors.length - 10} more errors
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {/* Action Buttons */}
                <div style={{ textAlign: 'right' }}>
                  <Space>
                    {batchImportResult.errors && batchImportResult.errors.length > 0 && (
                      <Button
                        icon={<DownloadOutlined />}
                        onClick={handleErrorLogDownload}
                      >
                        {t('health.batchImport.results.downloadErrors')}
                      </Button>
                    )}
                    <Button onClick={() => setBatchImportStep('upload')}>
                      {t('health.batchImport.results.backToUpload')}
                    </Button>
                    <Button type="primary" onClick={handleBatchImportClose}>
                      {t('health.batchImport.results.close')}
                    </Button>
                  </Space>
                </div>
              </div>
            )}
          </div>
        )}
      </Modal>

  {/* Generated by Zhuang */}
    </div>
  );
};

export default HealthRecords;
